const compare = $input.first().json;
const files = compare.files ?? [];

const relevantFiles = files
  .filter(file => {
    const path = file.filename ?? '';
    const lowerPath = path.toLowerCase();

    // Only Markdown files
    if (!lowerPath.endsWith('.md')) return false;

    // Exclude deleted files
    if (file.status === 'removed') return false;

    // Detect supported spec directories
    const isSpec =
      lowerPath.startsWith('brs/') ||
      lowerPath.includes('/brs/') ||
      lowerPath.includes('/srs/') ||
      lowerPath.includes('/sds/');

    if (!isSpec) return false;

    const fileName = lowerPath.split('/').pop();

    // Exclude reference documents
    const isReference =
      lowerPath.includes('/reference/') ||
      /^ref[-_]?(brs|srs|sds)(?:[-_.]|$)/i.test(fileName);

    if (isReference) return false;

    // Exclude auxiliary files
    const excluded =
      lowerPath.includes('/input/') ||
      lowerPath.includes('handover') ||
      lowerPath.includes('qareport') ||
      lowerPath.includes('approval-record');

    return !excluded;
  })
  .map(file => {
    const path = file.filename;
    const lowerPath = path.toLowerCase();

    let documentType = null;

    if (
      lowerPath.startsWith('brs/') ||
      lowerPath.includes('/brs/')
    ) {
      documentType = 'BRS';
    } else if (lowerPath.includes('/srs/')) {
      documentType = 'SRS';
    } else if (lowerPath.includes('/sds/')) {
      documentType = 'SDS';
    }

    return {
      filename: path,
      status: file.status,
      sha: file.sha,
      documentType,
      additions: file.additions ?? 0,
      deletions: file.deletions ?? 0,
      changes: file.changes ?? 0
    };
  });

return [{
  json: {
    baseCommit: compare.base_commit?.sha ?? null,
    currentCommit:
      $('Normalize Commit Info').first().json.currentCommitSha,
    relevantChangeCount: relevantFiles.length,
    hasRelevantChanges: relevantFiles.length > 0,
    relevantFiles
  }
}];

const items = $input.all();
const output = [];

for (const item of items) {
  const file = item.json.relevantFiles;

  if (!file?.filename || !file?.documentType) {
    continue;
  }

  const path = file.filename;
  const documentType = file.documentType.toUpperCase();

  if (!path.toLowerCase().endsWith('.md')) {
    continue;
  }

  if (file.status === 'removed') {
    continue;
  }

  const parts = path.split('/');

  const typeIndex = parts.findIndex(
    part => part.toUpperCase() === documentType
  );

  if (typeIndex === -1) {
    continue;
  }

  // TYPE/<SpecFolder>/<File>.md
  const afterType = parts.slice(typeIndex + 1);

  if (afterType.length !== 2) {
    continue;
  }

  const specFolder = afterType[0];
  const fileName = afterType[1];

  // Normalize: büyük/küçük harf, tire, alt çizgi farklarını kaldır
  const normalize = value =>
    value
      .replace(/\.md$/i, '')
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '');

  const normalizedFolder = normalize(specFolder);
  const normalizedFile = normalize(fileName);

  // Master dosyanın ismi, klasör ismiyle eşleşmeli
  if (normalizedFolder !== normalizedFile) {
    continue;
  }

  output.push({
    json: {
      filename: path,
      fileName,
      specName: specFolder,
      documentType,
      status: file.status,
      sha: file.sha,
      currentCommit: item.json.currentCommit,
      baseCommit: item.json.baseCommit
    }
  });
}

return output;

const results = $input.all();
const config = $('Pipeline Config').first().json;

function getErrorMessage(response) {
  const error = response.error ?? response.message;

  if (typeof error === 'string') {
    return error;
  }

  if (error && typeof error === 'object') {
    return error.message || JSON.stringify(error);
  }

  return 'Upload not confirmed';
}

function isTimeout(response, errorMessage) {
  const errorCode = String(
    response.error?.code ??
    response.code ??
    ''
  ).toUpperCase();

  const message = errorMessage.toLowerCase();

  return (
    ['ECONNABORTED', 'ETIMEDOUT', 'ESOCKETTIMEDOUT']
      .includes(errorCode) ||
    message.includes('timeout') ||
    message.includes('timed out') ||
    message.includes('etimedout') ||
    message.includes('econnaborted')
  );
}

return results.map((item, index) => {
  let source;

  try {
    source = $('Resolve KB Target').itemMatching(index).json;
  } catch (error) {
    throw new Error(
      `Cannot match upload result to source metadata: ${error.message}`
    );
  }

  const response = item.json;

  const requiredFields = [
    'commitId',
    'sourcePath',
    'specName',
    'documentType',
    'kbUrl'
  ];

  const missing = requiredFields.filter(
    field => !source[field]
  );

  if (missing.length) {
    throw new Error(
      `Missing metadata: ${missing.join(', ')}`
    );
  }

  const success =
    response.status === 'indexed' &&
    Boolean(response.doc_id);

  const errorMessage = success
    ? ''
    : getErrorMessage(response);

  let status;

  if (success) {
    status = 'SUCCESS';
  } else if (isTimeout(response, errorMessage)) {
    status = 'TIMEOUT';
  } else {
    status = 'FAILED';
  }

  return {
    json: {
      pipeline_id: config.repoName,
      commit_id: source.commitId,
      spec_path: source.sourcePath,
      spec_name: source.specName,
      document_type: source.documentType,
      kb_url: source.kbUrl,
      target_version:
        response.version ||
        source.targetVersion ||
        'v2.14',
      doc_id: response.doc_id || '',
      status,
      error_message: errorMessage,
      processed_at: new Date().toISOString()
    },
    pairedItem: { item: index }
  };
});

const expectedItems = $('Prepare KB Payload').all();
const results = $input.all();

const config = $('Pipeline Config').first().json;
const commitInfo = $('Normalize Commit Info').first().json;

const currentCommit = commitInfo.currentCommitSha;

// Expected documents
const expectedDocuments = expectedItems.map(item => ({
  spec_path: item.json.sourcePath,
  document_type: item.json.documentType,
  commit_id: item.json.commitId
}));

// Processed documents
const processedDocuments = results.map(item => ({
  spec_path:
    item.json.spec_path || item.json.sourcePath,

  document_type:
    item.json.document_type || item.json.documentType,

  commit_id:
    item.json.commit_id || item.json.commitId,

  status:
    String(item.json.status || '').toUpperCase(),

  doc_id:
    item.json.doc_id || '',

  operation:
    item.json.operation || '',

  error_message:
    item.json.error_message || ''
}));

const expectedCount = expectedDocuments.length;
const processedCount = processedDocuments.length;

// Status counts
const uploadedCount = processedDocuments.filter(
  item => item.status === 'SUCCESS'
).length;

const skippedCount = processedDocuments.filter(
  item => item.status === 'SKIPPED'
).length;

const recoveredCount = processedDocuments.filter(
  item => item.status === 'RECOVERED'
).length;

const pendingReviewCount = processedDocuments.filter(
  item => item.status === 'PENDING_REVIEW'
).length;
const pendingReviewDocuments = processedDocuments
  .filter(item => item.status === 'PENDING_REVIEW')
  .map(item => ({
    spec_path: item.spec_path,
    document_type: item.document_type,
    operation: item.operation,
    doc_id: item.doc_id,
    reason: item.error_message
  }));
const failedCount = processedDocuments.filter(
  item => ![
    'SUCCESS',
    'SKIPPED',
    'RECOVERED'
  ].includes(item.status)
).length;

// Identity
const makeKey = item =>
  JSON.stringify([
    item.spec_path,
    item.document_type
  ]);

const expectedKeys = expectedDocuments.map(makeKey);
const processedKeys = processedDocuments.map(makeKey);

const expectedSet = new Set(expectedKeys);
const processedSet = new Set(processedKeys);

// Missing
const missingDocuments = expectedDocuments.filter(
  item => !processedSet.has(makeKey(item))
);

// Unexpected
const unexpectedDocuments = processedDocuments.filter(
  item => !expectedSet.has(makeKey(item))
);

// Duplicates
const seen = new Set();

const duplicateDocuments = processedDocuments.filter(item => {
  const key = makeKey(item);

  if (seen.has(key)) return true;

  seen.add(key);
  return false;
});

// Invalid metadata
const invalidDocuments = processedDocuments.filter(
  item =>
    !item.spec_path ||
    !item.document_type ||
    !item.commit_id
);

// Commit mismatches
const commitMismatches = processedDocuments.filter(item => {
  const expected = expectedDocuments.find(
    doc => makeKey(doc) === makeKey(item)
  );

  return expected &&
    item.commit_id !== expected.commit_id;
});

// Missing document IDs
const missingDocIds = processedDocuments.filter(
  item =>
    ['SUCCESS', 'RECOVERED'].includes(item.status) &&
    !item.doc_id
);

// Successful statuses
const successfulCount =
  uploadedCount +
  skippedCount +
  recoveredCount;

// Final validation
const allSuccessful =
  expectedCount > 0 &&
  processedCount === expectedCount &&
  successfulCount === expectedCount &&
  failedCount === 0 &&
  pendingReviewCount === 0 &&
  expectedSet.size === expectedCount &&
  processedSet.size === expectedCount &&
  missingDocuments.length === 0 &&
  unexpectedDocuments.length === 0 &&
  duplicateDocuments.length === 0 &&
  invalidDocuments.length === 0 &&
  commitMismatches.length === 0 &&
  missingDocIds.length === 0 &&
  expectedDocuments.every(
    item => item.commit_id === currentCommit
  );

return [{
  json: {
    pipeline_id: config.repoName,
    currentCommit,

    expectedCount,
    processedCount,

    uploadedCount,
    skippedCount,
    recoveredCount,
    pendingReviewCount,
    failedCount,

    missingDocuments,
    unexpectedDocuments,
    duplicateDocuments,
    invalidDocuments,
    commitMismatches,
    missingDocIds,
    pendingReviewDocuments,


    allSuccessful,

    checkedAt: new Date().toISOString()
  }
}];

const config = $('Pipeline Config').first().json;

const kbUrls = {
  BRS: config.brsKbUrl,
  SRS: config.srsKbUrl,
  SDS: config.sdsKbUrl
};

return $input.all().map((item, index) => {
  const data = item.json;
  const type = String(data.documentType || '').toUpperCase();

  const baseUrl = kbUrls[type];

  if (!baseUrl) {
    throw new Error(`KB URL not configured for: ${type}`);
  }

  return {
    json: {
      ...data,
      documentType: type,
      kbUrl: baseUrl.replace(/\/$/, ''),
      uploadUrl:
        `${baseUrl.replace(/\/$/, '')}/api/v1/documents/upload`
    },
    pairedItem: { item: index }
  };
});

const token = $('Get Access Token').first().json.access_token;

if (!token || token.split('.').length !== 3) {
  throw new Error('JWT access token bulunamadı');
}

const payload = token.split('.')[1];
const claims = JSON.parse(
  Buffer.from(payload, 'base64url').toString('utf8')
);

return [{
  json: {
    issuer: claims.iss,
    audience: claims.aud,
    authorizedParty: claims.azp,
    issuedAt: claims.iat
      ? new Date(claims.iat * 1000).toISOString()
      : null,
    expiresAt: claims.exp
      ? new Date(claims.exp * 1000).toISOString()
      : null,
    scope: claims.scope,
    clientRoles: Object.keys(claims.resource_access || {}),
    realmRoles: claims.realm_access?.roles || [],
    expired: claims.exp
      ? Date.now() >= claims.exp * 1000
      : null
  }
}];

const original = $('Edit Fields1').all();

if (original.length !== 1) {
  throw new Error(
    `Expected one item in current loop, got ${original.length}`
  );
}

const item = original[0];

if (!item.binary?.data) {
  throw new Error('Missing binary.data');
}

return [{
  json: item.json,
  binary: item.binary
}];

const rows = $input.all().map(item => item.json);

const payload = $('Prepare KB Payload').item.json;

return [{
  json: {
    currentCommit: payload.commitId,
    currentSpecPath: payload.sourcePath,
    auditRecords: rows.map(row => ({
      id: row.id,
      commit_id: row.commit_id,
      spec_path: row.spec_path,
      status: row.status,
      doc_id: row.doc_id
    }))
  }
}];

const items = $input.all();
const config = $('Pipeline Config').first().json;

return items.map((item, index) => {
  const source = $('Resolve KB Target')
    .itemMatching(index).json;

  return {
    json: {
      pipeline_id: config.repoName,
      commit_id: source.commitId,
      spec_path: source.sourcePath,
      spec_name: source.specName,
      document_type: source.documentType,
      kb_url: source.kbUrl,
      target_version: source.targetVersion || 'v2.14',
      doc_id: '',
      status: 'PENDING_REVIEW',
      error_message:
        item.json.previous_error ||
        'Previous upload timed out; backend status requires verification',
      processed_at: new Date().toISOString()
    },
    pairedItem: { item: index }
  };
});

const metadataItems = $('Resolve KB Target').all();
const fileItems = $('Convert to File').all();
const hashItems = $input.all();

if (
  metadataItems.length !== fileItems.length ||
  fileItems.length !== hashItems.length
) {
  throw new Error('Item counts do not match');
}

return hashItems.map((hashItem, index) => {
  const metadata = metadataItems[index].json;
  const file = fileItems[index];
  const fileMd5 = hashItem.json.fileMd5;

  if (!fileMd5 || !file.binary?.data) {
    throw new Error(`Missing MD5 or binary at index ${index}`);
  }

  return {
    json: {
      ...metadata,
      fileMd5,
    },
    binary: file.binary,
    pairedItem: { item: index },
  };
});

const response = $json;
const original = $('Loop Over Items').item.json;
const binary = $('Loop Over Items').item.binary;

if (response.statusCode !== 200 || !Array.isArray(response.body)) {
  throw new Error('KB lookup failed or returned invalid data');
}

const version = original.targetVersion ?? 'v2.14';

const matches = response.body.filter(doc =>
  doc.doc_name === original.specName &&
  doc.type === 'md' &&
  doc.sources?.includes(version) &&
  doc.path?.split('/').pop() === original.fileName
);

const sameContent = matches.filter(doc =>
  typeof doc.md5 === 'string' &&
  doc.md5.toLowerCase() === original.fileMd5?.toLowerCase()
);

let decision;
let replaceDocId = null;

if (matches.length === 0) {
  decision = 'POST';
} else if (sameContent.length > 0) {
  decision = 'SKIP';
} else if (matches.length === 1) {
  decision = 'REPLACE';
  replaceDocId = matches[0].doc_id ?? matches[0].id;
} else {
  decision = 'PENDING_REVIEW';
}

return {
  json: {
    ...original,
    decision,
    replaceDocId,
    existingDocId:
      sameContent[0]?.doc_id ??
      sameContent[0]?.id ??
      matches[0]?.doc_id ??
      matches[0]?.id ??
      null,
    existingMd5: matches[0]?.md5 ?? null,
    kbMatchCount: matches.length,
    matchingContentCount: sameContent.length,
    duplicateCleanupRequired: matches.length > 1,
    duplicateDocIds: matches.map(doc => doc.doc_id ?? doc.id)
  },
  binary
};

const item = $input.item.json;
const config = $('Pipeline Config').first().json;

const required = [
  'commitId',
  'sourcePath',
  'specName',
  'documentType',
  'kbUrl',
  'fileMd5'
];

const missing = required.filter(field => !item[field]);

if (missing.length > 0) {
  throw new Error(
    `Missing SKIP metadata: ${missing.join(', ')}`
  );
}

if (item.decision !== 'SKIP') {
  throw new Error(
    `Unexpected decision for SKIP audit: ${item.decision}`
  );
}

return {
  json: {
    pipeline_id: config.repoName,
    commit_id: item.commitId,
    spec_path: item.sourcePath,
    spec_name: item.specName,
    document_type: item.documentType,
    kb_url: item.kbUrl,
    target_version: item.targetVersion ?? 'v2.14',
    doc_id: item.existingDocId ?? '',
    status: 'SKIPPED',
    error_message: '',
    processed_at: new Date().toISOString(),
    file_md5: item.fileMd5,
    operation: 'SKIP'
  }
};

const response = $input.item.json;
const config = $('Pipeline Config').first().json;

// POST ve REPLACE kollarından kaynak metadata'sını bul.
const source = $('Route KB Decision').item.json;

if (!['POST', 'REPLACE'].includes(source.decision)) {
  throw new Error(
    `Unexpected upload decision: ${source.decision}`
  );
}
const required = [
  'commitId',
  'sourcePath',
  'specName',
  'documentType',
  'kbUrl'
];

const missing = required.filter(field => !source[field]);

if (missing.length) {
  throw new Error(`Missing metadata: ${missing.join(', ')}`);
}

function getErrorMessage(value) {
  const error = value.error ?? value.message;

  if (typeof error === 'string') return error;
  if (error && typeof error === 'object') {
    return error.message || JSON.stringify(error);
  }

  return '';
}

const errorMessage = getErrorMessage(response);

const errorCode = String(
  response.error?.code ?? response.code ?? ''
).toUpperCase();

const statusCode = Number(
  response.statusCode ?? response.error?.statusCode ?? 0
);

const timeout =
  ['ETIMEDOUT', 'ECONNABORTED', 'ESOCKETTIMEDOUT']
    .includes(errorCode) ||
  /timeout|timed out|etimedout|econnaborted/i.test(errorMessage);

const success =
  response.status === 'indexed' &&
  Boolean(response.doc_id);

let status;
let finalError = errorMessage;

if (success) {
  status = 'SUCCESS';
  finalError = '';
} else if (timeout || !statusCode || statusCode >= 500) {
  status = 'PENDING_REVIEW';
  finalError ||= 'Upload outcome is not confirmed';
} else {
  status = 'FAILED';
  finalError ||= 'Upload failed';
}

return {
  json: {
    pipeline_id: config.repoName,
    commit_id: source.commitId,
    spec_path: source.sourcePath,
    spec_name: source.specName,
    document_type: source.documentType,
    kb_url: source.kbUrl,
    target_version:
      response.version ||
      source.targetVersion ||
      'v2.14',
    doc_id: success ? response.doc_id : '',
    status,
    error_message: finalError,
    processed_at: new Date().toISOString(),
    file_md5: source.fileMd5 || '',
    operation: source.decision
  }
};

const item = $input.item.json;
const config = $('Pipeline Config').first().json;

// REPLACE ve PENDING_REVIEW kararlarını kabul et
if (!['PENDING_REVIEW', 'REPLACE'].includes(item.decision)) {
  throw new Error(
    `Unexpected decision: ${item.decision}`
  );
}

const required = [
  'commitId',
  'sourcePath',
  'specName',
  'documentType',
  'kbUrl',
  'fileMd5'
];

const missing = required.filter(
  field => !item[field]
);

if (missing.length > 0) {
  throw new Error(
    `Missing metadata: ${missing.join(', ')}`
  );
}

// Karara göre hata açıklaması
let reason;

if (item.decision === 'REPLACE') {
  reason =
    `REPLACE temporarily disabled due to CogniaKB backend bug. ` +
    `Document ${item.specName} requires an update, ` +
    `but automatic replacement is unsafe. ` +
    `Existing KB document preserved.`;
} else {
  reason =
    `Multiple KB records (${item.kbMatchCount}) ` +
    `found for ${item.specName}; ` +
    `none matches GitHub MD5 ${item.fileMd5}. ` +
    `Manual review required.`;
}

return {
  json: {
    pipeline_id: config.repoName,
    commit_id: item.commitId,
    spec_path: item.sourcePath,
    spec_name: item.specName,
    document_type: item.documentType,
    kb_url: item.kbUrl,
    target_version: item.targetVersion ?? 'v2.14',
    doc_id: item.decision === 'REPLACE'
      ? (item.replaceDocId ?? '')
      : '',
    status: 'PENDING_REVIEW',
    error_message: reason,
    processed_at: new Date().toISOString(),
    file_md5: item.fileMd5,
    operation: item.decision === 'REPLACE'
      ? 'REPLACE'
      : 'REVIEW'
  }
};

const response = $input.item.json;
const source = $('Route KB Decision').item.json;
const config = $('Pipeline Config').first().json;

const version = source.targetVersion ?? 'v2.14';

const required = [
  'commitId',
  'sourcePath',
  'specName',
  'fileName',
  'documentType',
  'kbUrl',
  'fileMd5'
];

const missing = required.filter(field => !source[field]);

if (missing.length) {
  throw new Error(
    `Missing recovery metadata: ${missing.join(', ')}`
  );
}

if (!['POST', 'REPLACE'].includes(source.decision)) {
  throw new Error(
    `Unexpected recovery decision: ${source.decision}`
  );
}

if (
  response.statusCode !== 200 ||
  !Array.isArray(response.body)
) {
  throw new Error('KB recovery lookup returned invalid data');
}

const matches = response.body.filter(doc =>
  doc.doc_name === source.specName &&
  doc.type === 'md' &&
  doc.sources?.includes(version) &&
  doc.path?.split('/').pop() === source.fileName
);

const sameContent = matches.filter(doc =>
  typeof doc.md5 === 'string' &&
  doc.md5.toLowerCase() ===
    source.fileMd5.toLowerCase()
);

const recovered = sameContent.length > 0;

const status = recovered
  ? 'RECOVERED'
  : 'PENDING_REVIEW';

const reason = recovered
  ? 'Upload response failed, but matching content exists in KB.'
  : 'Upload response failed and matching content was not found. Manual verification required.';

return {
  json: {
    pipeline_id: config.repoName,
    commit_id: source.commitId,
    spec_path: source.sourcePath,
    spec_name: source.specName,
    document_type: source.documentType,
    kb_url: source.kbUrl,
    target_version: version,
    doc_id: recovered
      ? (sameContent[0].doc_id ?? sameContent[0].id ?? '')
      : '',
    status,
    error_message: recovered ? '' : reason,
    processed_at: new Date().toISOString(),
    file_md5: source.fileMd5,
    operation: source.decision
  }
};

const response = $input.item.json;
const source = $('Route KB Decision').item.json;
const config = $('Pipeline Config').first().json;

const required = [
  'commitId',
  'sourcePath',
  'specName',
  'documentType',
  'kbUrl',
  'fileMd5'
];

const missing = required.filter(field => !source[field]);

if (missing.length > 0) {
  throw new Error(
    `Missing metadata: ${missing.join(', ')}`
  );
}

const rawError =
  response.error?.message ??
  response.error ??
  response.message ??
  'Unknown KB lookup error';

const errorMessage =
  typeof rawError === 'string'
    ? rawError
    : JSON.stringify(rawError);

return {
  json: {
    pipeline_id: config.repoName,
    commit_id: source.commitId,
    spec_path: source.sourcePath,
    spec_name: source.specName,
    document_type: source.documentType,
    kb_url: source.kbUrl,
    target_version: source.targetVersion ?? 'v2.14',
    doc_id: '',
    status: 'PENDING_REVIEW',
    error_message:
      'Upload outcome could not be verified. ' +
      'KB recovery lookup failed: ' +
      errorMessage,
    processed_at: new Date().toISOString(),
    file_md5: source.fileMd5,
    operation: source.decision
  }
};
